package org.tabata.timber.core.timer

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFalse
import kotlin.test.assertNotNull
import kotlin.test.assertTrue
import kotlinx.coroutines.delay
import kotlinx.coroutines.test.runTest
import org.tabata.timber.domain.models.TimerState
import org.tabata.timber.domain.models.timer.PhaseType
import org.tabata.timber.domain.models.timer.TimerConfiguration

/**
 * Integration tests that verify the complete timer system works together
 * Tests the interaction between TimerController, PreciseTimerEngine, PhaseManager, and DriftCorrector
 */
class TimerIntegrationTest {
    
    /**
     * End-to-end test of a complete Tabata session
     */\n    @Test\n    fun testCompleteTabataSession() = runTest {\n        // Create a very short session for testing\n        val config = TimerConfiguration(\n            workDuration = 1,      // 1 second work\n            restDuration = 1,      // 1 second rest\n            cycles = 2,            // 2 cycles\n            sets = 1,              // 1 set\n            setBreakDuration = 1,  // 1 second set break (not used with 1 set)\n            warmupDuration = 1,    // 1 second warmup\n            cooldownDuration = 1   // 1 second cooldown\n        )\n        // Total duration: 1 + (1+1)*2 + 1 = 6 seconds\n        \n        // Use mock engine for predictable behavior\n        val mockEngine = MockTimerEngine()\n        val controller = TimerController(mockEngine)\n        \n        // Start session\n        val startResult = controller.startSession(config)\n        assertTrue(startResult is TimerController.TimerOperationResult.Success)\n        \n        // Verify initial state\n        assertTrue(mockEngine.isActive.value)\n        assertNotNull(mockEngine.currentConfiguration.value)\n        \n        // Test pause/resume\n        val pauseResult = controller.pauseSession()\n        assertTrue(pauseResult is TimerController.TimerOperationResult.Success)\n        \n        val resumeResult = controller.resumeSession()\n        assertTrue(resumeResult is TimerController.TimerOperationResult.Success)\n        \n        // Test skip operations\n        val skipResult = controller.skipToNext()\n        assertTrue(skipResult is TimerController.TimerOperationResult.Success)\n        \n        // Stop session\n        val stopResult = controller.stopSession()\n        assertTrue(stopResult is TimerController.TimerOperationResult.Success)\n        \n        assertFalse(mockEngine.isActive.value)\n    }\n    \n    /**\n     * Test phase transitions with real PhaseManager\n     */\n    @Test\n    fun testPhaseTransitions() {\n        val phaseManager = PhaseManager()\n        val config = TimerConfiguration(\n            workDuration = 20,\n            restDuration = 10,\n            cycles = 2,\n            sets = 1,\n            setBreakDuration = 0,\n            warmupDuration = 10,\n            cooldownDuration = 30\n        )\n        \n        // Test warmup phase\n        val warmupPhase = phaseManager.calculateCurrentPhase(5000L, config)\n        assertEquals(PhaseType.WARMUP, warmupPhase.phase)\n        assertEquals(5000L, warmupPhase.remainingTimeMs)\n        assertEquals(0, warmupPhase.currentCycle)\n        assertEquals(0, warmupPhase.currentSet)\n        \n        // Test first work phase\n        val workPhase = phaseManager.calculateCurrentPhase(15000L, config) // 10s warmup + 5s work\n        assertEquals(PhaseType.WORK, workPhase.phase)\n        assertEquals(15000L, workPhase.remainingTimeMs) // 15s remaining in work\n        assertEquals(1, workPhase.currentCycle)\n        assertEquals(1, workPhase.currentSet)\n        \n        // Test first rest phase\n        val restPhase = phaseManager.calculateCurrentPhase(35000L, config) // warmup + work + 5s rest\n        assertEquals(PhaseType.REST, restPhase.phase)\n        assertEquals(5000L, restPhase.remainingTimeMs)\n        assertEquals(1, restPhase.currentCycle)\n        assertEquals(1, restPhase.currentSet)\n        \n        // Test second work phase\n        val work2Phase = phaseManager.calculateCurrentPhase(45000L, config) // After first cycle + 5s work\n        assertEquals(PhaseType.WORK, work2Phase.phase)\n        assertEquals(15000L, work2Phase.remainingTimeMs)\n        assertEquals(2, work2Phase.currentCycle)\n        assertEquals(1, work2Phase.currentSet)\n        \n        // Test cooldown phase\n        val cooldownPhase = phaseManager.calculateCurrentPhase(70000L, config) // After all work/rest\n        assertEquals(PhaseType.COOLDOWN, cooldownPhase.phase)\n        assertEquals(30000L, cooldownPhase.remainingTimeMs)\n        assertTrue(cooldownPhase.isLastPhaseOfSession)\n    }\n    \n    /**\n     * Test drift correction functionality\n     */\n    @Test\n    fun testDriftCorrection() {\n        val driftCorrector = DriftCorrector()\n        val baseTime = 1000L\n        \n        // Simulate gradual drift accumulation\n        val drifts = listOf(10L, 25L, 45L, 75L, 120L) // Last one triggers correction\n        var lastMetrics: TimerPrecisionMetrics? = null\n        \n        drifts.forEachIndexed { index, drift ->\n            val metrics = driftCorrector.recordDrift(drift, baseTime + index * 1000L)\n            lastMetrics = metrics\n            \n            // Check if correction should be applied\n            val correction = driftCorrector.shouldApplyCorrection(drift, baseTime + index * 1000L)\n            if (drift > TimerPrecisionMetrics.CORRECTION_THRESHOLD_MS) {\n                assertNotNull(correction, \"Expected correction for drift: $drift\")\n            }\n        }\n        \n        lastMetrics?.let { metrics ->\n            assertTrue(metrics.sampleCount == drifts.size)\n            assertTrue(metrics.correctionsApplied > 0) // Should have applied at least one correction\n            assertEquals(120L, metrics.currentDriftMs)\n        }\n    }\n    \n    /**\n     * Test error handling across the system\n     */\n    @Test\n    fun testErrorHandling() = runTest {\n        val mockEngine = MockTimerEngine()\n        val controller = TimerController(mockEngine)\n        \n        // Test starting session when not in IDLE state\n        mockEngine.setTimerState(TimerState.WORK)\n        val startResult = controller.startSession(TimerConfiguration.createStandard())\n        assertTrue(startResult is TimerController.TimerOperationResult.Error)\n        assertEquals(TimerController.TimerErrorCode.INVALID_STATE, startResult.errorCode)\n        \n        // Reset to IDLE\n        mockEngine.setTimerState(TimerState.IDLE)\n        \n        // Test invalid configuration\n        val invalidConfig = TimerConfiguration(\n            workDuration = 0, // Invalid\n            restDuration = 10,\n            cycles = 1,\n            sets = 1,\n            setBreakDuration = 60\n        )\n        val invalidStartResult = controller.startSession(invalidConfig)\n        assertTrue(invalidStartResult is TimerController.TimerOperationResult.Error)\n        assertEquals(TimerController.TimerErrorCode.INVALID_CONFIGURATION, invalidStartResult.errorCode)\n        \n        // Test pause without active session\n        mockEngine.setIsActive(false)\n        val pauseResult = controller.pauseSession()\n        assertTrue(pauseResult is TimerController.TimerOperationResult.Error)\n        assertEquals(TimerController.TimerErrorCode.SESSION_NOT_FOUND, pauseResult.errorCode)\n        \n        // Test resume when not paused\n        mockEngine.setTimerState(TimerState.WORK)\n        val resumeResult = controller.resumeSession()\n        assertTrue(resumeResult is TimerController.TimerOperationResult.Error)\n        assertEquals(TimerController.TimerErrorCode.INVALID_STATE, resumeResult.errorCode)\n    }\n    \n    /**\n     * Test session info calculation\n     */\n    @Test\n    fun testSessionInfo() {\n        val mockEngine = MockTimerEngine()\n        val controller = TimerController(mockEngine)\n        val config = TimerConfiguration(\n            workDuration = 20,\n            restDuration = 10,\n            cycles = 4,\n            sets = 2,\n            setBreakDuration = 60,\n            warmupDuration = 10,\n            cooldownDuration = 30\n        )\n        \n        // Setup mock engine state\n        mockEngine.setCurrentConfiguration(config)\n        mockEngine.setCurrentSession(mockEngine.createMockSession())\n        mockEngine.setCurrentPhase(PhaseType.WORK)\n        mockEngine.setTimerState(TimerState.WORK)\n        mockEngine.setElapsedTimeMs(30000L) // 30 seconds elapsed\n        mockEngine.setRemainingTimeMs(15000L) // 15 seconds remaining in current phase\n        mockEngine.setCurrentCycle(2)\n        mockEngine.setCurrentSet(1)\n        \n        val sessionInfo = controller.getCurrentSessionInfo()\n        assertNotNull(sessionInfo)\n        \n        assertEquals(PhaseType.WORK, sessionInfo.currentPhase)\n        assertEquals(TimerState.WORK, sessionInfo.currentState)\n        assertEquals(30000L, sessionInfo.elapsedTimeMs)\n        assertEquals(15000L, sessionInfo.remainingTimeMs)\n        assertEquals(2, sessionInfo.currentCycle)\n        assertEquals(1, sessionInfo.currentSet)\n        \n        // Test progress calculation\n        val progress = sessionInfo.getProgressPercent()\n        assertTrue(progress >= 0.0 && progress <= 100.0)\n        \n        // Test formatted time\n        val formattedTime = sessionInfo.getFormattedRemainingTime()\n        assertEquals(\"00:15\", formattedTime) // 15 seconds = 00:15\n    }\n    \n    /**\n     * Test skip operations with validation\n     */\n    @Test\n    fun testSkipOperationsWithValidation() = runTest {\n        val mockEngine = MockTimerEngine()\n        val controller = TimerController(mockEngine)\n        \n        // Test skip when not active\n        mockEngine.setIsActive(false)\n        val skipInactiveResult = controller.skipToNext()\n        assertTrue(skipInactiveResult is TimerController.TimerOperationResult.Error)\n        assertEquals(TimerController.TimerErrorCode.SESSION_NOT_FOUND, skipInactiveResult.errorCode)\n        \n        // Test skip when paused\n        mockEngine.setIsActive(true)\n        mockEngine.setTimerState(TimerState.PAUSED)\n        val skipPausedResult = controller.skipToNext()\n        assertTrue(skipPausedResult is TimerController.TimerOperationResult.Error)\n        assertEquals(TimerController.TimerErrorCode.INVALID_STATE, skipPausedResult.errorCode)\n        \n        // Test skip in cooldown (not allowed)\n        mockEngine.setTimerState(TimerState.REST)\n        mockEngine.setCurrentPhase(PhaseType.COOLDOWN)\n        val skipCooldownResult = controller.skipToNext()\n        assertTrue(skipCooldownResult is TimerController.TimerOperationResult.Error)\n        assertEquals(TimerController.TimerErrorCode.OPERATION_NOT_ALLOWED, skipCooldownResult.errorCode)\n        \n        // Test valid skip\n        mockEngine.setTimerState(TimerState.WORK)\n        mockEngine.setCurrentPhase(PhaseType.WORK)\n        val skipValidResult = controller.skipToNext()\n        assertTrue(skipValidResult is TimerController.TimerOperationResult.Success)\n    }\n    \n    /**\n     * Test precision metrics integration\n     */\n    @Test\n    fun testPrecisionMetricsIntegration() {\n        val mockEngine = MockTimerEngine()\n        val controller = TimerController(mockEngine)\n        \n        // Setup precision metrics\n        val metrics = TimerPrecisionMetrics(\n            currentDriftMs = 75L,\n            maxDriftMs = 100L,\n            averageDriftMs = 65.5,\n            correctionsApplied = 2,\n            lastCorrectionTimeMs = 5000L,\n            isWithinPrecision = false,\n            sampleCount = 10,\n            driftStandardDeviation = 25.3\n        )\n        \n        mockEngine.setPrecisionMetrics(metrics)\n        mockEngine.setCurrentConfiguration(TimerConfiguration.createStandard())\n        mockEngine.setCurrentSession(mockEngine.createMockSession())\n        \n        val sessionInfo = controller.getCurrentSessionInfo()\n        assertNotNull(sessionInfo)\n        \n        assertEquals(metrics, sessionInfo.precisionMetrics)\n        assertEquals(75L, sessionInfo.precisionMetrics.currentDriftMs)\n        assertEquals(2, sessionInfo.precisionMetrics.correctionsApplied)\n        assertFalse(sessionInfo.precisionMetrics.isWithinPrecision)\n    }\n    \n    /**\n     * Test multiple set configuration with set breaks\n     */\n    @Test\n    fun testMultipleSetConfiguration() {\n        val phaseManager = PhaseManager()\n        val config = TimerConfiguration(\n            workDuration = 10,\n            restDuration = 5,\n            cycles = 2,\n            sets = 3,\n            setBreakDuration = 30,\n            warmupDuration = 0,\n            cooldownDuration = 0\n        )\n        \n        // Test first set, first cycle\n        val phase1 = phaseManager.calculateCurrentPhase(5000L, config) // 5s into first work\n        assertEquals(PhaseType.WORK, phase1.phase)\n        assertEquals(1, phase1.currentSet)\n        assertEquals(1, phase1.currentCycle)\n        \n        // Test set break\n        val setBreakTime = (10 + 5) * 2 * 1000L // After first set (30s)\n        val phaseBreak = phaseManager.calculateCurrentPhase(setBreakTime, config)\n        assertEquals(PhaseType.SET_BREAK, phaseBreak.phase)\n        assertEquals(1, phaseBreak.currentSet) // Still set 1 during break\n        \n        // Test second set, first cycle\n        val secondSetTime = setBreakTime + 30000L + 5000L // After set break + 5s into work\n        val phase2 = phaseManager.calculateCurrentPhase(secondSetTime, config)\n        assertEquals(PhaseType.WORK, phase2.phase)\n        assertEquals(2, phase2.currentSet) // Now in set 2\n        assertEquals(1, phase2.currentCycle) // First cycle of set 2\n    }\n}"